package com.example.agendapersonal;
import com.example.agendapersonal.sync.*;import com.example.agendapersonal.ui.*;import com.example.agendapersonal.data.DatabaseHelper;import com.example.agendapersonal.eventos.SeriesEvento;
import android.database.sqlite.SQLiteDatabase;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.time.*;import java.util.*;
/** Incluye las 17 comprobaciones anteriores de persistencia. Datos UUID aislados. */
public class DiaSyncInstrumentedTest extends PersistenciaSyncInstrumentedTest {
 void tarea(SQLiteDatabase d,String fecha,String estado,String categoria,String borrada){d.execSQL("INSERT INTO tareas(id,owner_id,descripcion,fecha_vencimiento,categoria,prioridad,estado_especial,created_at,deleted_at) VALUES (?,?,?, ?,?,'MEDIA',?,'2026-11-05T00:00:00Z',?)",new Object[]{UUID.randomUUID().toString(),OWNER,"Prueba diaria",fecha,categoria,estado,borrada});}
 @Test public void diaRealExcluye602HistoricasAunqueSeCrearonHoy(){try(DatabaseHelper h=new DatabaseHelper(context)){SQLiteDatabase d=h.getWritableDatabase();d.beginTransaction();try{for(int i=0;i<602;i++)tarea(d,"2020-01-01","FINALIZADO","ESTUDIOS",null);tarea(d,"2026-11-05",null,"OTRA",null);tarea(d,"2026-11-05","FINALIZADO","FREELANCE",null);tarea(d,"2026-11-05","CANCELADO","ESTUDIOS",null);tarea(d,"2026-11-05","POSTERGADO","ESTUDIOS",null);tarea(d,"2026-11-06",null,"ESTUDIOS",null);tarea(d,"2026-11-05",null,"ESTUDIOS","2026-11-05T01:00:00Z");d.setTransactionSuccessful();}finally{d.endTransaction();}}ResumenDia r=ProgresoDia.cargar(context,LocalDateTime.of(2026,11,5,12,0));assertEquals(2,r.total);assertEquals(1,r.finalizadas);assertEquals(1,r.pendientes);assertEquals(50,r.porcentaje());}
 @Test public void recurrenciaDeHoySeCuentaSinDuplicarExcepcionMaterializada()throws Exception{String serie=UUID.randomUUID().toString(),inicial=UUID.randomUUID().toString();JSONObject plantilla=new JSONObject().put("descripcion","Semanal").put("categoria","OTRA").put("hora","13:00").put("alarmaActivada","false");JSONObject segmento=new JSONObject().put("desde",0).put("inicio","2026-10-29").put("unidad","SEMANAS").put("cada",1).put("dia",29).put("mes",10).put("plantilla",plantilla);JSONObject cfg=new JSONObject().put("version",1).put("evento_inicial",inicial).put("segmentos",new JSONArray().put(segmento));try(DatabaseHelper h=new DatabaseHelper(context)){h.getWritableDatabase().execSQL("INSERT INTO series_eventos(id,owner_id,frecuencia,configuracion_personalizada) VALUES (?,?,'SEMANAL',?)",new Object[]{serie,OWNER,cfg.toString()});}LocalDateTime ahora=LocalDateTime.of(2026,11,5,12,0);assertEquals(1,ProgresoDia.cargar(context,ahora).total);String id=SeriesEvento.ocurrencia(context,serie,1).texto("id");try(DatabaseHelper h=new DatabaseHelper(context)){h.getWritableDatabase().execSQL("INSERT INTO eventos(id,owner_id,descripcion,categoria,fecha,hora,serie_id) VALUES (?,?,'Semanal','OTRA','2026-11-05','13:00',?)",new Object[]{id,OWNER,serie});}assertEquals(1,ProgresoDia.cargar(context,ahora).total);}
 @Test public void envioConfirmadoEsDurableYReintentoNoSumaDosVeces()throws Exception{CambioSync c=cambio("personas",persona("Salida",1),0);log(c);store.confirmarEnviados(OWNER,Collections.singletonList(c));store.confirmarEnviados(OWNER,Collections.singletonList(c));assertEquals(1,store.enviadosConfirmados(OWNER));store.close();store=new AlmacenSync(context);assertEquals(1,store.enviadosConfirmados(OWNER));}
 @Test public void reflejoDeMiPropioEnvioNoEsUnaRecepcion()throws Exception{JSONObject p=persona("Mi envío",1);insertar(context,p);CambioSync original=cambio("personas",p,0);JSONObject j=new JSONObject(original.documento).put("device_id",DEVICE);CambioSync c=new CambioSync(original.id,original.fecha,j.toString());log(c);store.confirmarEnviados(OWNER,Collections.singletonList(c));j.put("_snapshot",true);CambioSync eco=new CambioSync(c.id,c.fecha,j.toString());recibir(eco);assertEquals(1,store.enviadosConfirmados(OWNER));assertEquals(0,store.recibidosConfirmados(OWNER));}
 @Test public void contadorRecibidosNoSumaRevisionesSinCambioNiReintentos()throws Exception{CambioSync primero=snapshot(persona("Uno",1));recibir(primero);recibir(primero);assertEquals(1,store.recibidosConfirmados(OWNER));recibir(snapshot(persona("Uno",1)));assertEquals(1,store.recibidosConfirmados(OWNER));recibir(snapshot(persona("Dos",8)));assertEquals(2,store.recibidosConfirmados(OWNER));}
 @Test public void recuperaTotalesDeEnviosPreviosYLosConservaTrasLimpieza()throws Exception{CambioSync previo=cambio("personas",persona("Ya enviado",1),0);JSONObject j=new JSONObject(previo.documento).put("device_id",context.getSharedPreferences("agenda_identidad",0).getString("device_id",""));CambioSync c=new CambioSync(previo.id,previo.fecha,j.toString());log(c);try(DatabaseHelper h=new DatabaseHelper(context)){h.getWritableDatabase().execSQL("INSERT INTO sync_outbox_sent VALUES (?,?,'2000-01-01T00:00:00Z')",new Object[]{OWNER,c.id});}assertEquals(1,store.enviadosConfirmados(OWNER));store.limpiarConfirmados(OWNER);assertEquals(0,cantidad("sync_changes"));assertEquals(1,store.enviadosConfirmados(OWNER));store.close();store=new AlmacenSync(context);assertEquals(1,store.enviadosConfirmados(OWNER));}
}
